export function patchNotesScreen({version,esc,btn}){
 return `<div class="patch-intro"><span class="eyebrow">현재 버전 ${esc(version)}</span>${btn('menu','메뉴','quiet')}</div><div class="patch-list">${PATCH_NOTES.map((p,i)=>`<article class="patch-entry" aria-labelledby="patch-${i}"><div class="patch-heading"><h3 id="patch-${i}">v${esc(p.version)}${i===0?' <small>최신</small>':''}</h3><time datetime="${esc(p.date)}">${esc(p.date)}</time></div><h4>${esc(p.title)}</h4><ul>${p.changes.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></article>`).join('')}</div>`;
}
